package org.securemail.ui;

import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import javafx.application.Platform;
import javafx.geometry.Bounds;
import javafx.scene.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Stage;
import org.securemail.client.appearance.Appearance;
import org.securemail.client.attachments600.*;
import org.securemail.client.crypto.*;
import org.securemail.client.storage.LocalStore;
import org.securemail.protocol.*;

/** Actual JavaFX bindings/letter-password+FF1 UI. Descriptor is a UI fixture, not a network/Tor download. */
public final class MailStreamingSmoke600 {
  private static <T>T fx(Callable<T> task)throws Exception{var future=new CompletableFuture<T>();Platform.runLater(()->{try{future.complete(task.call());}catch(Throwable failure){future.completeExceptionally(failure);}});return future.get(20,TimeUnit.SECONDS);}
  private static Object field(Object value,String name)throws Exception{var f=value.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(value);}
  private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
  private static List<Node> nodes(Node root){List<Node> all=new ArrayList<>();all.add(root);if(root instanceof Parent p)for(var child:p.getChildrenUnmodifiable())all.addAll(nodes(child));return all;}
  private static Button button(Node root,String title){return nodes(root).stream().filter(n->n instanceof Button b&&b.getText().equals(title)).map(n->(Button)n).findFirst().orElseThrow();}
  private static void image(Stage stage,Path path)throws Exception{Parent root=stage.getScene().getRoot();root.applyCss();root.layout();for(Node n:nodes(root))if(n instanceof HBox||n instanceof VBox||n instanceof FlowPane){var controls=((Parent)n).getChildrenUnmodifiable().stream().filter(c->c instanceof Control&&c.isVisible()&&c.isManaged()).toList();for(int a=0;a<controls.size();a++)for(int b=a+1;b<controls.size();b++){Bounds x=controls.get(a).getBoundsInParent(),y=controls.get(b).getBoundsInParent();check(Math.min(x.getMaxX(),y.getMaxX())-Math.max(x.getMinX(),y.getMinX())<=1||Math.min(x.getMaxY(),y.getMaxY())-Math.max(x.getMinY(),y.getMinY())<=1,"Overlapping Mail controls");}}var snapshot=stage.getScene().snapshot(null);var out=new java.awt.image.BufferedImage((int)snapshot.getWidth(),(int)snapshot.getHeight(),java.awt.image.BufferedImage.TYPE_INT_ARGB);for(int y=0;y<out.getHeight();y++)for(int x=0;x<out.getWidth();x++)out.setRGB(x,y,snapshot.getPixelReader().getArgb(x,y));javax.imageio.ImageIO.write(out,"png",path.toFile());}
  private static Appearance.Settings scale(Appearance.Settings s,int scale){return new Appearance.Settings(s.theme(),s.mode(),s.lightTheme(),s.darkTheme(),s.lightAt(),s.darkAt(),scale,s.density(),s.typography(),s.components(),s.layout(),s.backdrop());}
  public static void main(String[] args)throws Exception{
    Path output=Path.of(args[0]);Files.createDirectories(output);System.setProperty("aegis.profile",Files.createTempDirectory("aegis-stream-ui6-").toString());var ready=new CompletableFuture<Void>();Platform.startup(()->{Platform.setImplicitExit(false);ready.complete(null);});ready.get();var worker=Executors.newSingleThreadExecutor();ThemeManager themes=fx(ThemeManager::new);VBox[] hostRef=new VBox[1];Stage stage=fx(()->{themes.initialize();Stage window=new Stage();var shell=new BorderPane();var content=new VBox();hostRef[0]=content;ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);shell.setCenter(scroll);themes.apply(shell);window.setScene(new Scene(shell,1024,768));window.show();return window;});
    var sender=Identity.create();var receiver=Identity.create();char[] password="stream viewer fixture password".toCharArray(),code="246810".toCharArray();byte[] master=StreamingAttachmentCipher.newFileKey();String candidate=HexFormat.of().formatHex(master);long now=System.currentTimeMillis(),size=StreamingAttachmentCipher.MAX_PLAINTEXT;var context=new StreamingAttachmentCipher.Context(UUID.randomUUID().toString(),sender.userId(),receiver.userId(),size);var descriptor=new AttachmentManifest600.File("Длинное русское название защищённого документа для проверки компоновки.pdf",context,StreamingAttachmentCipher.ciphertextSize(size),"c".repeat(64),"d".repeat(64),now+3600000,3600000);byte[] wrapped=LetterEnvelope.seal(candidate,password,code),envelope=LetterEnvelope.seal("Защищённый текст письма",password,code);var manifest=new AttachmentManifest600("a".repeat(64),true,List.of(descriptor),wrapped);byte[] encoded=manifest.encode();MailViewer[] held=new MailViewer[1];
    try{
      var plain=PlainMessage.streaming("Проверка потокового вложения", "",envelope,null,encoded);var packet=new AutomaticEncryption(java.time.Clock.systemUTC()).encrypt(plain,3600,3600000,sender,"sender",new UserInfo(receiver.userId(),"receiver",receiver.publicKey(),null));var item=new LocalStore.HistoryItem(packet.messageId(),"sender",false,"Получено",now,now+3600000,packet);
      fx(()->{var host=hostRef[0];held[0]=new MailViewer(stage,themes,plain,item,worker,System::currentTimeMillis,host,new MailViewer.Actions(){public void reply(LocalStore.HistoryItem i,PlainMessage p){}public void forward(LocalStore.HistoryItem i,PlainMessage p,String b,PlainMessage.FileBundle f){if(f!=null)f.close();}public void original(MailContext c){}public boolean unknown(){return false;}});check(((Button)field(held[0],"download")).isDisabled(),"File available before password/FF1");check(field(held[0],"streamCandidate")==null,"Master available before reveal");((PasswordField)field(held[0],"password")).setText(new String(password));button(stage.getScene().getRoot(),"Открыть").fire();return null;});worker.submit(()->{}).get(20,TimeUnit.SECONDS);fx(()->null);
      fx(()->{check(((Button)field(held[0],"download")).isDisabled(),"File available after only letter password");check(field(held[0],"streamCandidate")==null,"FF1 layer bypassed");((SecretField)field(held[0],"code")).hidden.setText(new String(code));button(stage.getScene().getRoot(),"Показать результат").fire();return null;});worker.submit(()->{}).get(20,TimeUnit.SECONDS);fx(()->null);
      fx(()->{check(field(held[0],"streamCandidate").equals(candidate),"Actual FF1 master candidate differs");check(!((Button)field(held[0],"download")).isDisabled(),"Revealed incoming file stayed disabled");check(((TextArea)field(held[0],"text")).getText().equals("Защищённый текст письма"),"Body changed by attachment format");return null;});
      fx(()->{stage.hide();return null;});
      // Each matrix case owns a new Glass surface. Monocle21 otherwise reuses an undersized pixel buffer after a live resize.
      for(String theme:List.of("minimal-dark","minimal-light"))for(int scale:List.of(100,200))for(int[] sizeValue:List.of(new int[]{800,600},new int[]{1024,768})){
        Stage[] frame=new Stage[1];MailViewer[] viewer=new MailViewer[1];
        fx(()->{themes.preview(scale(themes.settings().manual(theme),scale));frame[0]=new Stage();VBox host=new VBox();ScrollPane scroll=new ScrollPane(host);scroll.setFitToWidth(true);BorderPane shell=new BorderPane(scroll);frame[0].setScene(new Scene(shell,sizeValue[0],sizeValue[1]));themes.apply(shell);frame[0].show();var copy=PlainMessage.streaming("Проверка потокового вложения","",envelope,null,encoded);viewer[0]=new MailViewer(frame[0],themes,copy,item,worker,System::currentTimeMillis,host,new MailViewer.Actions(){public void reply(LocalStore.HistoryItem i,PlainMessage p){}public void forward(LocalStore.HistoryItem i,PlainMessage p,String body,PlainMessage.FileBundle files){if(files!=null)files.close();}public void original(MailContext c){}public boolean unknown(){return false;}});((PasswordField)field(viewer[0],"password")).setText(new String(password));button(frame[0].getScene().getRoot(),"Открыть").fire();return null;});worker.submit(()->{}).get(20,TimeUnit.SECONDS);fx(()->null);
        fx(()->{((SecretField)field(viewer[0],"code")).hidden.setText(new String(code));button(frame[0].getScene().getRoot(),"Показать результат").fire();return null;});worker.submit(()->{}).get(20,TimeUnit.SECONDS);fx(()->null);Thread.sleep(100);
        fx(()->{check(candidate.equals(field(viewer[0],"streamCandidate")),"Matrix FF1 key mismatch");image(frame[0],output.resolve("streamed-"+theme+"-"+scale+"-"+sizeValue[0]+"x"+sizeValue[1]+".png"));viewer[0].close();frame[0].hide();return null;});
      }
      fx(()->{((SecretField)field(held[0],"code")).hidden.setText("wrong candidate");check(field(held[0],"streamCandidate")==null,"Changing FF1 code retained old attachment key");check(((Button)field(held[0],"download")).isDisabled(),"Changing code left download enabled");held[0].close();check(field(held[0],"streamCandidate")==null,"Closed viewer retained attachment candidate");return null;});System.out.println("PASS: actual streamed Mail view; password then FF1 before file access; actual candidate matches; code change/close revoke; 8 real light/dark PNGs at 800/1024,100/200%. Scope=Monocle UI+local descriptor fixture; real HTTP/Tor download not claimed.");
    }finally{fx(()->{if(held[0]!=null)held[0].close();themes.close();stage.hide();return null;});worker.shutdownNow();manifest.close();Arrays.fill(master,(byte)0);Arrays.fill(encoded,(byte)0);Arrays.fill(wrapped,(byte)0);Arrays.fill(envelope,(byte)0);Arrays.fill(password,'\0');Arrays.fill(code,'\0');Platform.exit();}
  }
}
